True def transform(grid):
    g=[row[:] for row in grid]
    # Extend the marked diagonal ray in both directions through the background.
    h,w=len(g),len(g[0]); bg=g[0][0]
    pairs=[]
    for r in range(h-1):
        for c in range(w):
            for dc in (-1,1):
                if 0<=c+dc<w and g[r][c]==g[r+1][c+dc] and g[r][c]!=bg:
                    pairs.append((r,c,dc,g[r][c]))
    for r,c,dc,v in pairs:
        for dr,step in ((-1,-dc),(1,dc)):
            rr,cc=r,c
            while 0<=rr+dr<h and 0<=cc+step<w:
                rr+=dr;cc+=step
                if g[rr][cc]==bg:g[rr][cc]=v
    return g

